# jamovi glue only. All logic lives in spec.R / validate.R / build_plot.R /
# spec_to_code.R so it can be tested without jamovi.
# `layerPlotBase` is generated by jmvtools into R/layerplot.h.R on build.

layerPlotClass <- if (requireNamespace("jmvcore", quietly = TRUE)) R6::R6Class(
  "layerPlotClass",
  inherit = layerPlotBase,
  private = list(

    .run = function() {
      msgs <- self$results$messages
      show <- function(lines) {
        msgs$setContent(paste(lines, collapse = "\n"))
        msgs$setVisible(TRUE)
      }

      if (is.null(self$options$x) && is.null(self$options$y)) {
        show("Select at least an X or a Y variable to start.")
        return()
      }

      spec <- spec_from_options(self$options)
      res  <- validate_spec(spec, self$data)

      if (length(res$errors)) {
        show(c("The plot cannot be drawn yet:", paste0("- ", res$errors)))
        return()
      }
      if (length(res$warnings))
        show(c("Note:", paste0("- ", res$warnings)))

      self$results$plot$setState(list(spec = spec, data = self$data))

      if (isTRUE(self$options$showCode))
        self$results$code$setContent(spec_to_code(spec, self$data))
    },

    .plot = function(image, ggtheme, theme, ...) {
      state <- image$state
      if (is.null(state))
        return(FALSE)
      print(build_plot(state$spec, state$data))
      TRUE
    }
  )
)
